131	// String 将千分之一克格式化为克数字符串，去掉末尾多余的 0。
132	func (g gramsMilli) String() string {
133		sign := ""
134		v := int64(g)
135		if v < 0 {
136			sign = "-"
137			v = -v
138		}
139		w, f := v/1000, v%1000
140		if f == 0 {
141			return sign + strconv.FormatInt(w, 10)
142		}
143		fs := strings.TrimRight(fmt.Sprintf("%03d", f), "0")
144		return sign + strconv.FormatInt(w, 10) + "." + fs
145	}
