147	// multiplyPortions 将每份克数与计划份数相乘，计算某物料的应投量
148	// （每份克数 × 计划份数）。它是数量规则 planRequirements 使用的底层
149	// 定点运算，创建批次、调整草稿、读取校验与批次数量核对最终都经由
150	// planRequirements 调用到这里：
151	//   - 计划份数必须为正整数——份数为零或负数的已保存批次即数据损坏，
152	//     也不能据此算出零或负的应投量；
153	//   - 相乘结果必须能用千分之一克（int64 个 milli）精确表示：克数本身
154	//     已是千分之一克的整数倍，整数相乘不引入更小的单位，不存在舍入；
155	//     结果超过 maxGramsMilli（9223372036854775.807 克）时返回错误。
156	//
157	// 这里只做一种物料一次乘法，按物料分别判断上限的职责在 planRequirements：
158	// 不与同批次其他物料的应投量相加；恰好等于上限合法，再大即溢出。
159	// 计算不回绕、不截断、不舍入。
160	func multiplyPortions(g gramsMilli, portions int) (gramsMilli, error) {
161		if portions <= 0 {
162			return 0, errors.New("份数必须为正整数")
163		}
164		v := int64(g)
165		if v > (1<<63-1)/int64(portions) {
166			return 0, fmt.Errorf("应投量超出上限 %s 克：%s 克 × %d 份无法精确表示",
167				maxGramsMilli, g, portions)
168		}
169		return gramsMilli(v * int64(portions)), nil
170	}
